package com.obysoft.faithOS.entity;
import java.time.*;import jakarta.persistence.*;
@Entity @Table(name="member_messages") public class MemberMessage{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Church church;@ManyToOne(optional=false)private User sender;@ManyToOne(optional=false)private User recipient;@Column(nullable=false,columnDefinition="text")private String message;@Column(name="created_at",nullable=false)private LocalDateTime createdAt;@Column(name="read_at")private LocalDateTime readAt;@Column(name="expires_at")private LocalDateTime expiresAt;@Column(name="attachment_name")private String attachmentName;@Column(name="attachment_type")private String attachmentType;@Column(name="attachment_size")private Long attachmentSize;@Column(name="attachment_data",columnDefinition="bytea")private byte[] attachmentData;@PrePersist void before(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;}public Church getChurch(){return church;}public void setChurch(Church v){church=v;}public User getSender(){return sender;}public void setSender(User v){sender=v;}public User getRecipient(){return recipient;}public void setRecipient(User v){recipient=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getReadAt(){return readAt;}public void setReadAt(LocalDateTime v){readAt=v;}public LocalDateTime getExpiresAt(){return expiresAt;}public void setExpiresAt(LocalDateTime v){expiresAt=v;}public String getAttachmentName(){return attachmentName;}public void setAttachmentName(String v){attachmentName=v;}public String getAttachmentType(){return attachmentType;}public void setAttachmentType(String v){attachmentType=v;}public Long getAttachmentSize(){return attachmentSize;}public void setAttachmentSize(Long v){attachmentSize=v;}public byte[] getAttachmentData(){return attachmentData;}public void setAttachmentData(byte[] v){attachmentData=v;}
}
